    // Iterate over all possible substrings of the first string
    for (int i = 0; i < firstString.length(); i++) {
        for (int j = i + 1; j <= firstString.length(); j++) {
            String substr = firstString.substring(i, j);
            String inverse = new StringBuilder(substr).reverse().toString();

            boolean allContains = true; // Flag to check if all strings contain the substring or its inverse

            // Check for each string in the list
            for (String str : strings) {
                if (!str.contains(substr) && !str.contains(inverse)) {
                    allContains = false;
                    break;
                }
            }

            // Update maxLen if a larger valid substring is found
            if (allContains) {
                maxLen = Math.max(maxLen, substr.length());
            }
        }
    }

    return maxLen;
}

