private static void permute(int[] arr, int start, Set<String> permutations) {
  if (start == arr.length) {
    if (isSquareArray(arr)) {
      permutations.add(arrayToString(arr));
    }
    return;
  }

  for (int i = start; i < arr.length; i++) {
    swap(arr, i, start);
    permute(arr, start + 1, permutations);
    swap(arr, i, start);
  }
}

private static boolean isSquareArray(int[] arr) {
  for (int i = 0; i < arr.length - 1; i++) {
    if (!isPerfectSquare(arr[i] + arr[i + 1])) {
      return false;
    }
  }
  return true;
}

private static boolean isPerfectSquare(int num) {
  int sqrt = (int) Math.sqrt(num);
  return num == sqrt * sqrt;
}

private static void swap(int[] arr, int i, int j) {
  int temp = arr[i];
  arr[i] = arr[j];
  arr[j] = temp;
}

private static String arrayToString(int[] arr) {
  StringBuilder sb = new StringBuilder();
  for (int num : arr) {
    sb.append(num).append(",");
  }
  return sb.toString();
}

